package vn.svframe.svframemmo.skill;
import vn.svframe.svframelib.SVFrameLib;import vn.svframe.svframelib.config.YamlLite;import vn.svframe.svframelib.util.configobject.MapConfigObject;import vn.svframe.svframemmo.skill.list.*;import vn.svframe.svframemmo.script.mechanic.*;import java.io.IOException;import java.nio.file.Path;import java.util.*;
public final class SVFrameMMOSkillBootstrap {private SVFrameMMOSkillBootstrap(){}public static void register(Path dir)throws IOException{var skills=SVFrameLib.inst().getSkills();skills.registerBuiltinSkillHandlerType(Ambers.class);skills.registerBuiltinSkillHandlerType(Neptune_Gift.class);skills.registerBuiltinSkillHandlerType(Sneaky_Picky.class);skills.registerMechanic("mana",ManaMechanic::new);skills.registerMechanic("stamina",StaminaMechanic::new);skills.registerMechanic("stellium",StelliumMechanic::new);registerHandler(skills,new Ambers(config(dir,"ambers.yml","AMBERS")));registerHandler(skills,new Neptune_Gift(config(dir,"neptune-gift.yml","NEPTUNE_GIFT")));registerHandler(skills,new Sneaky_Picky(config(dir,"sneaky-picky.yml","SNEAKY_PICKY")));}
private static MapConfigObject config(Path dir,String file,String id)throws IOException{return new MapConfigObject(id,YamlLite.map(YamlLite.parse(dir.resolve(file))));}
private static void registerHandler(vn.svframe.svframelib.manager.SkillManager manager,vn.svframe.svframelib.skill.handler.SkillHandler<?> handler){if(manager.getHandler(handler.getId())==null)manager.registerSkillHandler(handler);}
}
